//! Frozen base-export outcomes, not outputs regenerated by the candidate tests.
use sim::{model::Outcome, trace::Trace};
use std::{fs::File, path::Path};
#[test]
fn every_migrated_trace_preserves_both_complete_legacy_outcomes() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    for id in [
        "F1", "F2", "F3", "F4", "F5", "F13", "F14", "F15", "F15b", "F16",
    ] {
        let legacy: serde_json::Value =
            serde_json::from_reader(File::open(root.join(format!("traces/{id}-v1.json"))).unwrap())
                .unwrap();
        let baseline: serde_json::Value = serde_json::from_reader(
            File::open(root.join(format!("fixtures/legacy-outcomes/{id}-outcomes.json"))).unwrap(),
        )
        .unwrap();
        let trace: Trace =
            serde_json::from_reader(File::open(root.join(format!("traces/{id}-v2.json"))).unwrap())
                .unwrap();
        assert_eq!(
            baseline["source_commit"],
            "a984d632d4733fdaa95d21bfb0a5af98e18a2582"
        );
        assert_eq!(
            serde_json::to_value(&trace.config).unwrap(),
            legacy["config"]
        );
        assert_eq!(
            serde_json::to_value(&trace.commands).unwrap(),
            legacy["commands"]
        );
        assert_eq!(
            serde_json::to_value(&trace.expected_failure).unwrap(),
            legacy["expected_failure"]
        );
        assert_eq!(baseline["historical"], legacy["expected_outcome"]);
        let historical: Outcome = serde_json::from_value(baseline["historical"].clone()).unwrap();
        let corrected: Outcome = serde_json::from_value(baseline["corrected"].clone()).unwrap();
        assert_eq!(
            trace.verify_recorded().unwrap(),
            historical,
            "{id} historical"
        );
        assert_eq!(
            trace.corrected().verify_recorded().unwrap(),
            corrected,
            "{id} corrected"
        );
        assert!(!trace.budget_snapshot.is_empty());
        assert!(trace.budget_snapshot.len() < legacy["budget_snapshot"].as_object().unwrap().len());
    }
}
#[test]
fn legacy_migration_refuses_used_value_and_outcome_changes() {
    let raw: serde_json::Value =
        serde_json::from_str(include_str!("../traces/F16-v1.json")).unwrap();
    let mut changed = raw.clone();
    changed["budget_snapshot"]["OwnerPoll"] = "changed".into();
    assert_eq!(
        Trace::migrate_legacy(changed, "build".into(), "a".repeat(64)).unwrap_err(),
        "legacy_used_budget_mismatch:OwnerPoll"
    );
    let mut changed = raw;
    changed["expected_outcome"]["log"] = serde_json::json!([]);
    assert_eq!(
        Trace::migrate_legacy(changed, "build".into(), "a".repeat(64)).unwrap_err(),
        "legacy_outcome_mismatch"
    );
}
